import { describeStations } from './solution';
import type { StationRecord } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

equal(describeStations([]).length, 0, 'empty input');
const readings = [1, 2, 6];
const stations: StationRecord[] = [
  { stationId: 'S-1', label: 'North', readings },
  { stationId: 'S-2', readings: [] },
  { stationId: 'S-1', label: 'North', readings: [-1.5, 0.5] },
];
const descriptions = describeStations(stations);
equal(descriptions.length, 3, 'one result per station');
equal(descriptions[0], 'Station: S-1, Label: North, Mean: 3', 'labeled arithmetic mean');
equal(descriptions[1], 'Station: S-2, Mean: N/A', 'empty readings without label');
equal(descriptions[2], 'Station: S-1, Label: North, Mean: -0.5', 'duplicates and fractional values retained');
equal(readings.length, 3, 'readings array not mutated');
equal(readings[0], 1, 'reading value not mutated');
equal(stations[0].stationId, 'S-1', 'station object not mutated');

const decimal = describeStations([{ stationId: 'D', readings: [0.1, 0.2] }]);
equal(decimal[0], `Station: D, Mean: ${String((0.1 + 0.2) / 2)}`, 'normal JavaScript number conversion');

throwsTypeError(() => describeStations(null as unknown as readonly StationRecord[]), 'stations must be an array');
throwsTypeError(() => describeStations([null as unknown as StationRecord]), 'station must be an object');
throwsTypeError(() => describeStations([{ stationId: ' ', readings: [] }]), 'station ID must be non-empty');
throwsTypeError(() => describeStations([{ stationId: 'S', label: '', readings: [] }]), 'provided label must be non-empty');
throwsTypeError(() => describeStations([{ stationId: 'S', readings: null as unknown as readonly number[] }]), 'readings must be an array');
throwsTypeError(() => describeStations([{ stationId: 'S', readings: [NaN] }]), 'NaN reading');
throwsTypeError(() => describeStations([{ stationId: 'S', readings: [Infinity] }]), 'infinite reading');
throwsTypeError(() => describeStations([{ stationId: 'S', readings: ['1' as unknown as number] }]), 'reading must be numeric');

